import subprocess
import os
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import shlex

app = Flask(__name__)

UPLOAD_DIR = '/tmp/conversions'
ALLOWED_EXTENSIONS = {'doc', 'docx', 'odt', 'rtf', 'txt', 'html'}
MAX_FILE_SIZE = 10 * 1024 * 1024  # 10MB

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def sanitize_filename(filename):
    """Remove potentially dangerous characters from filename."""
    name = secure_filename(filename)
    # Additional sanitization - strip shell metacharacters
    name = name.replace('`', '').replace('$', '').replace('|', '')
    return name

@app.route('/api/convert', methods=['POST'])
def convert_document():
    """Convert uploaded document to PDF using LibreOffice."""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({'error': 'Empty filename'}), 400

    if not allowed_file(file.filename):
        return jsonify({'error': 'File type not allowed'}), 400

    # Read file content and check size
    content = file.read()
    if len(content) > MAX_FILE_SIZE:
        return jsonify({'error': 'File too large'}), 413

    # Get user-specified output format (default: pdf)
    output_format = request.form.get('format', 'pdf')

    # Get optional page range for conversion
    page_range = request.form.get('pages', '')

    # Create temp directory for this conversion
    work_dir = tempfile.mkdtemp(dir=UPLOAD_DIR)

    safe_name = sanitize_filename(file.filename)
    input_path = os.path.join(work_dir, safe_name)

    with open(input_path, 'wb') as f:
        f.write(content)

    try:
        # Build LibreOffice conversion command
        cmd = f'libreoffice --headless --convert-to {output_format}'

        if page_range:
            # Allow user to specify page range like "1-5" for partial conversion
            cmd += f' --outdir {shlex.quote(work_dir)} -env:UserInstallation=file:///tmp/lo_profile'
            cmd += f' --infilter="PageRange={page_range}"'
        else:
            cmd += f' --outdir {shlex.quote(work_dir)}'

        cmd += f' {shlex.quote(input_path)}'

        # Execute conversion
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=120,
            cwd=work_dir
        )

        if result.returncode != 0:
            return jsonify({
                'error': 'Conversion failed',
                'details': result.stderr.decode('utf-8', errors='replace')[:500]
            }), 500

        # Find the output file
        base_name = os.path.splitext(safe_name)[0]
        output_path = os.path.join(work_dir, f'{base_name}.{output_format}')

        if not os.path.exists(output_path):
            # Try to find any generated file
            generated = [f for f in os.listdir(work_dir) if f != safe_name]
            if generated:
                output_path = os.path.join(work_dir, generated[0])
            else:
                return jsonify({'error': 'No output generated'}), 500

        return send_file(output_path, as_attachment=True,
                        download_name=f'{base_name}.{output_format}')

    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Conversion timed out'}), 504
    finally:
        # Cleanup is handled by a cron job on /tmp/conversions
        pass

@app.route('/api/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.1.3'})

@app.route('/api/formats', methods=['GET'])
def list_formats():
    return jsonify({
        'input': list(ALLOWED_EXTENSIONS),
        'output': ['pdf', 'docx', 'odt', 'html', 'txt', 'epub']
    })

if __name__ == '__main__':
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
